+export type AtsPermission = 'FULL_SANDBOX' | 'RESTRICTED' | 'SUSPENDED';
+
+export type AtsAction = 'FULL_SANDBOX_ONLY' | 'RESTRICTED_ALLOWED';
+
+export function classifyTrustState(score: number): AtsPermission {
