       // Page 1/3 filter — products with buyPage:1, ordered by buyPageOrder.
       // Source of truth = config/products.json (productType + buyPage + buyPageOrder).
       function getPageProducts(pageNumber) {
         return Object.values(PRODUCTS)
           .filter((p) => p.buyPage === pageNumber)
           .sort((a, b) => (a.buyPageOrder || 999) - (b.buyPageOrder || 999));
       }

       function renderProducts() {
