  function createProductCard(product) {
    const card = document.createElement("div");
    card.className = "product-card";
    card.id = "product-" + product.id;
    card.dataset.productId = product.id;
    card.dataset.price = product.price;
    card.dataset.name = product.name;
    card.dataset.productType = product.productType || "";
    card.setAttribute("itemscope", "");
    card.setAttribute("itemtype", "https://schema.org/Product");

    if (product.featured) card.classList.add("featured");
    card.classList.add("live-payment");

    const revolutUrl = getRevolutUrl(product);
    const paypalUrl = getPayPalUrl(product);
    const detailsUrl = product.detailsUrl || "../products/";
    const hasPaidLinks = !!(product.revolutLink || product.price > 0);

    let featuresHTML = "";
    if (product.features && product.features.length) {
      featuresHTML =
        '<div class="product-features">' +
        product.features
          .map(
            (f) =>
              '<div class="product-feature-item"><span class="product-feature-check">\u2713</span><span>' +
              esc(f) +
              "</span></div>",
          )
          .join("") +
        "</div>";
    }

    const painHTML = product.pain ? '<p class="pain-hook">' + esc(product.pain) + "</p>" : "";
    const proofHTML = product.proofChip
      ? '<span class="proof-chip" title="Source: ' +
        esc(product.proofSource || "") +
        '">\u2713 ' +
        esc(product.proofChip) +
        "</span>"
      : "";

    const buyButtons = hasPaidLinks
      ? '<div class="btn-group">' +
        '<a href="' +
        esc(revolutUrl) +
        '" class="btn btn-revolut" target="_blank" rel="noopener" title="Pay with Revolut">Buy &middot; Revolut</a>' +
        '<a href="' +
        esc(paypalUrl) +
        '" class="btn btn-paypal" target="_blank" rel="noopener" title="Pay with PayPal">Buy &middot; PayPal</a>' +
        "</div>"
      : '<div class="btn-group">' +
        '<a href="https://dws10.com/contact/?subject=' +
        encodeURIComponent("Order: " + product.name + " (" + product.id + ")") +
        '" class="btn btn-primary" style="flex:1">Request quote &rarr;</a>' +
        "</div>";

    const bundleBtn =
      '<button type="button" class="btn-bundle" data-bundle-id="' +
      esc(product.id) +
      '">+ Add to bundle</button>';

    card.innerHTML =
      '<img src="' +
      esc(product.image) +
      '" alt="' +
      esc(product.name) +
      '" class="product-image" itemprop="image" onerror="this.src=\'../static/images/Firehorse_Store.jpg\'">' +
      '<div class="product-content">' +
      '<h2 class="product-title" itemprop="name">' +
      esc(product.name) +
      "</h2>" +
      proofHTML +
      painHTML +
      // Price is intentionally NOT shown on the card (enterprise products lead with
