<script>
  (function () {
    "use strict";

    var CATEGORY_LABELS = {
      platform: "Platform & Products",
      "ai-cloud": "AI &amp; Cloud",
      advisory: "Expert Advisory &amp; Training",
      digital: "Digital Services",
      hardware: "Sovereign Hardware",
      "add-on": "Add-ons",
      subscription: "Required Subscriptions",
    };
    var CATEGORY_ORDER = [
      "platform",
      "ai-cloud",
      "advisory",
      "digital",
      "hardware",
      "add-on",
      "subscription",
    ];
    var TIER_COLOR = {
      T0: "#94a3b8",
      T1: "#0ea5e9",
      T2: "#16a34a",
      T3: "#7c3aed",
      T4: "#dc2626",
      land: "#ea580c",
      meter: "#475569",
    };
    function tierBadge(tier) {
      if (!tier) return "";
      var label =
        tier === "land" || tier === "meter"
          ? tier.charAt(0).toUpperCase() + tier.slice(1)
          : tier;
      var c = TIER_COLOR[tier] || "#475569";
      return (
        '<span style="display:inline-block;background:' +
        c +
        ";color:#fff;font-size:0.7rem;font-weight:700;padding:2px 7px;" +
        'border-radius:4px;margin-right:8px;letter-spacing:0.05em;">' +
        label +
        "</span>"
      );
    }
    function replacesLine(p) {
      var r = p && p.replaces;
      if (!r || typeof r !== "object") return "";
      var role = r.role || "human role";
      var fte = r.fteCount;
      var cost = r.fullyLoadedAnnualCostEUR;
      var pct = null;
      var price = p.price || 0;
      var unit = p.priceUnit || "";
      if (cost && price) {
        var annual = unit === "per-month" ? price * 12 : unit === "per-year" ? price : null;
        if (annual) pct = Math.round((annual / cost) * 100);
      }
      var tail = pct !== null ? " at ~" + pct + "% of fully loaded cost" : "";
      var fteStr = fte === undefined || fte === null ? "?" : String(fte);
      return (
        '<div class="replaces-line" style="font-size:0.82rem;color:#34d399;' +
        'margin-top:6px;font-style:italic;">Replaces ' +
        escapeHtml(role) +
        " ≈ " +
        escapeHtml(fteStr) +
        " FTE" +
        escapeHtml(tail) +
        ".</div>"
      );
    }
    function upsellLine(p) {
      var nxt = p && p.nextUpsellSku;
      if (!nxt) return "";
      return (
        '<div class="upsell-line" style="font-size:0.78rem;color:#94a3b8;' +
        'margin-top:2px;">Next upsell: <strong style="color:#cbd5e1;">' +
        escapeHtml(nxt) +
        "</strong></div>"
      );
    }

    function eur(n) {
      if (n === null || n === undefined) return "—";
      try {
        return new Intl.NumberFormat("en-IE", {
          style: "currency",
          currency: "EUR",
          maximumFractionDigits: 0,
        }).format(n);
      } catch (e) {
        return "€" + String(n);
      }
    }

    function unitLabel(type) {
      switch (type) {
        case "hourly":
          return "per hour";
        case "daily":
          return "per day";
