const active=Object.values(data.products).filter(p=>p.productType!=='archived'&&p.deploymentColor!=='blue').map(p=>p.id);
const lifetimeOtherProductIds=active.filter(id=>!primaryProductIds.includes(id));
const governance={
  version:'1.0',
  primarySurface:'https://dws10.com/buy/',
  primaryProductIds,
  otherSurface:'https://lifetime.fi/price-list/',
  lifetimeOtherProductIds,
  defaults:{
    owner:'Lifetime Oy',
    scopeSource:'description',
    deliveryBoundary:'Delivery is limited to the catalog description, listed features and price note. Hardware, travel, third-party licences and integrations are excluded unless explicitly included; additional scope requires a written quote.'
  },
  buyerByCategory:{
    platform:'EU-regulated organizations procuring sovereign software and compliance outcomes',
    'ai-cloud':'EU organizations deploying AI, cloud or agent-engineering capability',
    advisory:'Teams procuring expert delivery, implementation or training outcomes',
    digital:'Organizations procuring bounded digital workflow services',
    hardware:'Organizations deploying customer-controlled sovereign edge AI',
    'add-on':'Existing DWS IQ or Firehorse customers purchasing an add-on'
  },
  excludedStates:{blue:'BLUE/pilot — internal sign-off required; not publicly quoted',archived:'Archived — retained for historical traceability; not for sale'}
};
const block='  "publicationGovernance": '+JSON.stringify(governance,null,2).replace(/\n/g,'\n  ')+',\n';
const marker='  "merchant": {';
if(!text.includes(marker)) throw new Error('merchant marker missing');
text=text.replace(marker,block+marker);
JSON.parse(text);
fs.writeFileSync(path,text);
fs.copyFileSync(path,'landing-pages/dws10-com/config/products.json');
console.log({primary:primaryProductIds.length,other:lifetimeOtherProductIds.length,active:active.length});
