  border-left: 3px solid #ef4444;
  border-radius: 4px;
}
.proof-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: rgba(16, 185, 129, 0.12);
  color: #6ee7b7;
  border: 1px solid rgba(16, 185, 129, 0.3);
  padding: 4px 10px;
  border-radius: 14px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.3px;
  margin-bottom: 10px;
  text-transform: uppercase;
}
.page-tease {
  display: block;
  font-size: 0.78rem;
  color: #fdba74;
  background: rgba(249, 115, 22, 0.08);
  border: 1px dashed rgba(249, 115, 22, 0.35);
  padding: 8px 12px;
  border-radius: 6px;
  margin: 8px 0 18px;
  font-weight: 600;
  text-align: center;
  letter-spacing: 0.2px;
}
.pagination-bar {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12px;
  margin: 32px 0 20px;
  padding: 16px;
  background: rgba(30, 41, 59, 0.5);
  border: 1px solid rgba(96, 165, 250, 0.2);
  border-radius: 12px;
}
.pagination-bar a,
.pagination-bar span {
  padding: 8px 16px;
  border-radius: 6px;
  text-decoration: none;
  font-weight: 700;
  font-size: 0.92rem;
  color: #cbd5e1;
  border: 1px solid rgba(148, 163, 184, 0.25);
  transition: all 0.2s;
}
.pagination-bar a:hover {
  border-color: #60a5fa;
  color: #60a5fa;
  background: rgba(96, 165, 250, 0.08);
}
.pagination-bar a.is-current,
.pagination-bar span.is-current {
  background: linear-gradient(135deg, #2563eb, #1d4ed8);
  color: #ffffff;
  border-color: transparent;
}
.pagination-bar .label {
  color: #94a3b8;
  font-size: 0.85rem;
  border: none;
  padding: 0 8px;
}

/* Product Features */
.product-features {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 16px;
  padding: 12px;
  background: rgba(15, 23, 42, 0.5);
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.05);
}
.product-feature-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.85rem;
  color: #cbd5e1;
}
.product-feature-check {
  color: #4ade80;
  font-weight: 700;
  flex-shrink: 0;
  font-size: 0.9rem;
}

.product-excerpt {
  font-size: 0.9rem;
  color: #94a3b8;
  margin-bottom: 20px;
  flex-grow: 1;
  line-height: 1.5;
}

/* Buttons */
.btn-group {
  display: flex;
  gap: 8px;
  margin-top: auto;
  flex-wrap: wrap;
}
.btn {
  flex: 1;
  text-align: center;
  padding: 12px 16px;
  border-radius: 6px;
  text-decoration: none;
  font-weight: 600;
  font-size: 0.9rem;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
  min-width: 0;
}
.btn-primary {
  background: linear-gradient(135deg, #2563eb, #1d4ed8);
  color: white;
}
.btn-primary:hover {
  background: linear-gradient(135deg, #3b82f6, #2563eb);
  transform: translateY(-1px);
}
.btn-secondary {
  background: transparent;
  color: #60a5fa;
  border: 1px solid #60a5fa;
}
.btn-secondary:hover {
  background: rgba(96, 165, 250, 0.1);
}
.btn-revolut {
  background: linear-gradient(135deg, #0075eb, #0058b7);
  color: white;
}
.btn-revolut:hover {
  background: linear-gradient(135deg, #1a85f0, #0068d8);
  transform: translateY(-1px);
}
.btn-paypal {
  background: linear-gradient(135deg, #ffc439, #ffb300);
  color: #003087;
}
.btn-paypal:hover {
  background: linear-gradient(135deg, #ffd060, #ffc439);
  transform: translateY(-1px);
}
.btn-details {
  background: transparent;
  color: #60a5fa;
  border: 1px solid #60a5fa;
  display: block;
  text-align: center;
  margin-top: 8px;
  padding: 10px 16px;
  border-radius: 6px;
  text-decoration: none;
  font-weight: 600;
  font-size: 0.9rem;
  transition: all 0.2s;
}
.btn-details:hover {
  background: rgba(96, 165, 250, 0.1);
}

/* Payment Badge */
.payment-badge {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}
.payment-badge span {
  font-size: 0.8rem;
  color: #64748b;
}

/* Featured Badge */
.featured {
  position: relative;
}
.featured::before {
  content: "RECOMMENDED";
  position: absolute;
  top: 12px;
  right: 12px;
  background: linear-gradient(135deg, #2563eb, #1d4ed8);
  color: white;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  z-index: 10;
  box-shadow: 0 2px 8px rgba(37, 99, 235, 0.4);
}
.featured {
  border-color: rgba(96, 165, 250, 0.3);
}

/* Live Payment Badge */
.live-payment::after {
  content: "\2713 LIVE";
  position: absolute;
  top: 12px;
  left: 12px;
  background: linear-gradient(135deg, #10b981, #059669);
  color: white;
  padding: 4px 10px;
  border-radius: 20px;
  font-size: 0.65rem;
  font-weight: 700;
  z-index: 10;
}

/* Trust Section */
.trust-section {
  text-align: center;
  margin: 60px 0 40px;
  padding: 40px 20px;
  background: rgba(30, 41, 59, 0.5);
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.1);
}
.trust-section h3 {
  color: #e2e8f0;
  margin-bottom: 20px;
  font-size: 1.3rem;
}

