        ? CONFIG.revolutFallbackLink
        : "https://revolut.me/lifetimeoy";
    var priceNumber = typeof product.price === "number" ? product.price : Number(product.price);
    if (!Number.isFinite(priceNumber) || priceNumber <= 0) {
      return fallback;
    }
    if (!Number.isInteger(priceNumber)) {
      return fallback;
    }
    return fallback + "/" + priceNumber + "EUR";
  }

