           <span id="productCount">Loading products…</span>
         </div>
         <div id="content"><p>Loading the canonical catalog…</p></div>
       </section>

       <footer>
         <p>Lifetime Oy · Business ID 0772407-9 · VAT ID FI07724079 · Laidunmaanraitti 2 A 25, 02330 Espoo, Finland</p>
         <p>Pricing source: <a href="https://dws10.com/config/products.json">dws10.com/config/products.json</a> · <a href="https://dws10.com/price-list/">Primary DWS price list</a></p>
       </footer>
     </main>
     <script>
       (function () {
         "use strict";
         var sourceUrl = "https://dws10.com/config/products.json";
         function setText(id, value) { document.getElementById(id).textContent = value; }
         function price(product) {
           var amount = Number(product.price);
           if (!Number.isFinite(amount) || amount <= 0) return "Pilot / POA";
           return amount.toLocaleString("fi-FI") + " €";
         }
         function detailsUrl(product) {
           if (!product.detailsUrl) return "https://dws10.com/contact/";
           return new URL(product.detailsUrl.replace(/^\.\.\//, ""), "https://dws10.com/").href;
         }
         function render(data) {
           var list = Object.values(data.products || {})
             .filter(function (product) { return product && product.deploymentColor === "blue"; })
             .sort(function (a, b) { return String(a.name).localeCompare(String(b.name)); });
           setText("version", data.priceVersion || "1.26");
           setText("effective", (data.priceList && data.priceList.effectiveDate) || "2026-08-18");
           setText("nextReview", (data.priceList && data.priceList.nextReviewDate) || "2026-11-18");
           setText("productCount", list.length + " products");
           var table = document.createElement("table");
           var head = document.createElement("thead");
           head.innerHTML = "<tr><th>ID</th><th>Product</th><th>Price</th><th>Unit</th><th>Action</th></tr>";
           table.appendChild(head);
           var body = document.createElement("tbody");
           list.forEach(function (product) {
             var row = document.createElement("tr");
             var id = document.createElement("td"); id.textContent = product.id || product.sku || "—";
             var productCell = document.createElement("td");
             var name = document.createElement("div"); name.className = "name"; name.textContent = product.name || product.id;
             var note = document.createElement("div"); note.className = "note"; note.textContent = product.priceNote || product.description || "";
             var badge = document.createElement("span"); badge.className = "pilot"; badge.textContent = "BLUE / PILOT";
             productCell.append(name, note, badge);
             var priceCell = document.createElement("td"); priceCell.className = "price"; priceCell.textContent = price(product);
             var unit = document.createElement("td"); unit.textContent = product.priceUnit || product.type || "—";
             var action = document.createElement("td");
             var link = document.createElement("a"); link.href = detailsUrl(product); link.textContent = "Details"; link.rel = "noopener";
             action.appendChild(link);
             row.append(id, productCell, priceCell, unit, action);
             body.appendChild(row);
           });
           table.appendChild(body);
           var wrapper = document.createElement("div"); wrapper.className = "table-wrap"; wrapper.appendChild(table);
           document.getElementById("content").replaceChildren(wrapper);
         }
         fetch(sourceUrl, { headers: { Accept: "application/json" } })
           .then(function (response) { if (!response.ok) throw new Error("Catalog request failed (" + response.status + ")"); return response.json(); })
           .then(render)
           .catch(function (error) { var box=document.createElement("p"); box.className="error"; box.textContent="Could not load the price list: " + error.message; document.getElementById("content").replaceChildren(box); });
       })();
     </script>
