}

function escapeHtml(s) {
  if (s === null || s === undefined) return "";
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function fmtDate(iso) {
  if (!iso) return "—";
  try {
    var d = new Date(iso);
    return d.toISOString().slice(0, 10);
  } catch (e) {
    return iso;
  }
}

function render(data) {
  var pl = data.priceList || {};
  var policy = pl.policy || {};
  var gov = pl.governance || {};
  var portfolio = data.commercialPortfolio || {};
  var seriousIds = portfolio.seriousProductIds;
  if (!Array.isArray(seriousIds) || seriousIds.length !== 13) {
    throw new Error("commercialPortfolio.seriousProductIds must contain exactly 13 IDs");
  }
  var seriousLookup = {};
  seriousIds.forEach(function (id) { seriousLookup[id] = true; });
  var catalogProducts = data.products || {};
  var publicProducts = Object.keys(catalogProducts).map(function (key) {
    return catalogProducts[key];
  }).filter(function (product) {
    return product && product.deploymentColor !== "blue" &&
      product.archived !== true && product.productType !== "archived";
  });
  if (publicProducts.length !== 49) {
    throw new Error("Expected 49 public products; found " + publicProducts.length);
  }
  seriousIds.forEach(function (id) {
    var product = catalogProducts[id];
    if (!product) throw new Error("Serious product missing: " + id);
    if (product.deploymentColor === "blue" || product.archived === true || product.productType === "archived") {
      throw new Error("Serious product is not public: " + id);
    }
  });

  function writeCatalogPrice(elementId, product) {
    if (!product || !Number.isFinite(Number(product.price))) {
      throw new Error("Catalog price missing for " + elementId);
    }
    document.getElementById(elementId).textContent = eur(Number(product.price));
  }
  writeCatalogPrice("priceControlRoom", catalogProducts["edge-node-gn100"]);
  writeCatalogPrice("priceDgxSpark", catalogProducts["LF-DGX-SPARK"]);
  writeCatalogPrice("priceSituationRoom", catalogProducts["LF-SITROOM-001"]);
  writeCatalogPrice("priceIgxOrin", catalogProducts["LF-IGX-ORIN"]);
  writeCatalogPrice("priceNvidiaInstall", catalogProducts["LF-NVIDIA-INSTALL"]);
  writeCatalogPrice("priceModelUpdates", (data.subscriptions || {})["LF-SOV-MODEL-SUB"]);
  writeCatalogPrice("priceHardwareLow", catalogProducts["LF-DGX-SPARK"]);
  writeCatalogPrice("priceHardwareHigh", catalogProducts["LF-IGX-ORIN"]);

  document.getElementById("mVersion").textContent = pl.version || "—";
  document.getElementById("mEffective").textContent = fmtDate(pl.effectiveDate);
  document.getElementById("mNext").textContent = fmtDate(pl.nextReviewDate);
  document.getElementById("mCurrency").textContent = policy.currency || "EUR";
  document.getElementById("mVat").textContent =
    policy.vatTreatment === "B2B_VAT_0" ? "B2B · 0%" : policy.vatTreatment || "—";
  document.getElementById("mTerms").textContent = policy.paymentTerms || "Net 14";
  document.getElementById("mQuote").textContent = policy.quoteValidity || "30 days";

  if (gov.legalEntity) document.getElementById("lName").textContent = gov.legalEntity;
  if (gov.address) document.getElementById("lAddr").textContent = gov.address;
  if (gov.businessId) document.getElementById("lBuid").textContent = gov.businessId;
  if (gov.vatId) document.getElementById("lVat").textContent = gov.vatId;
  if (gov.owner) document.getElementById("lOwner").textContent = gov.owner;
  if (gov.salesEmail) {
    var a = document.getElementById("lSales");
    a.href = "https://dws10.com/contact/";
    a.textContent = gov.salesEmail;
  }

  var products = Object.assign({}, catalogProducts);

