cd /home/admin100/dws6/.copilot-worktrees/price-list-v1-25 && cat >> lifetime.fi/price-list/index.html <<'HTML'
    <script>
      (function () {
        "use strict";
        var expectedIds = Array.from({ length: 13 }, function (_, index) {
          return "LTF-CONSULT-" + String(index + 1).padStart(3, "0");
        });
        function setText(id, value) { document.getElementById(id).textContent = value; }
        function addField(list, label, value) {
          var term = document.createElement("dt"); term.textContent = label;
          var detail = document.createElement("dd"); detail.textContent = value;
          list.append(term, detail);
        }
        function render(data) {
          var packages = data.packages;
          if (data.version !== "1.25") throw new Error("Consulting publication version must be 1.25");
          if (!Array.isArray(packages) || packages.length !== 13) throw new Error("Expected exactly 13 consulting packages");
          packages.forEach(function (item, index) {
            if (item.id !== expectedIds[index]) throw new Error("Unexpected package ID or order at position " + (index + 1));
          });
          setText("version", data.version);
          setText("effective", data.effectiveDate);
          setText("nextReview", data.nextReviewDate);
          setText("owner", data.owner);
          setText("packageCount", packages.length + " packages supporting 13 serious products");
          var grid = document.createElement("div"); grid.className = "package-grid";
          packages.forEach(function (item) {
            var card = document.createElement("article"); card.className = "package";
            var id = document.createElement("div"); id.className = "package-id"; id.textContent = item.id;
            var heading = document.createElement("h3"); heading.textContent = item.name;
            var pills = document.createElement("div"); pills.className = "pills";
            ["Owner: " + item.owner, "Supports: " + item.supportedProduct + " (" + item.supportedProductId + ")"].forEach(function (text) {
              var pill = document.createElement("span"); pill.className = "pill"; pill.textContent = text; pills.appendChild(pill);
            });
            var price = document.createElement("div"); price.className = "price"; price.textContent = item.price.display;
            var list = document.createElement("dl");
            addField(list, "Buyer", item.buyer);
            addField(list, "Outcome / scope", item.outcomeScope);
            addField(list, "Workflow", item.workflow);
            addField(list, "Deliverable", item.deliverable);
            addField(list, "Customer inputs", item.inputs);
            addField(list, "Delivery window", item.deliveryWindow);
            addField(list, "Acceptance boundary", item.acceptanceBoundary);
            addField(list, "Exclusions", item.exclusions);
            var boundary = document.createElement("p"); boundary.className = "boundary";
            boundary.textContent = "Delivery boundary: " + item.deliveryWindow + " Acceptance boundary: " + item.acceptanceBoundary;
            card.append(id, heading, pills, price, list, boundary); grid.appendChild(card);
          });
          document.getElementById("content").replaceChildren(grid);
        }
        fetch("/config/consulting-packages.json", { cache: "no-store", headers: { Accept: "application/json" } })
          .then(function (response) { if (!response.ok) throw new Error("HTTP " + response.status); return response.json(); })
          .then(render)
          .catch(function (error) { var box=document.createElement("p"); box.className="error"; box.textContent="Could not load the governed consulting packages: " + error.message; document.getElementById("content").replaceChildren(box); setText("packageCount", "Unavailable"); });
      })();
    </script>
    <script src="/shared-assets/footer/ironclad-footer.js"></script>
  </body>
</html>
HTML
